(6443077, 956667, 128323, '<td valign="top">Amazing sky!</td>', 'Amazing sky!', '2011-06-13 14:29:31.000000', NULL, 1),
(6443078, 956518, 58634, '<td valign="top">Looks a bit washed out to me, especially  at the center. I think it could also use more color. Composition is good. That tree is pretty cool looking.</td>', 'Looks a bit washed out to me, especially  at the center. I think it could also use more color. Composition is good. That tree is pretty cool looking.', '2011-06-13 14:29:58.000000', NULL, 1),
(6443079, 956655, 58634, '<td valign="top">I like this shot, and the sense of movement and ''speed'' it''s got. Contrast is good and makes the image pop. My only critique is the people''s feet being cut off, as well as the gentleman to the right.</td>', 'I like this shot, and the sense of movement and ''speed'' it''s got. Contrast is good and makes the image pop. My only critique is the people''s feet being cut off, as well as the gentleman to the right.', '2011-06-13 14:31:11.000000', NULL, 1),
(6443080, 956590, 10785, '<td valign="top">Super interesting photo. Not a typical calendar image in my view. But I suppose one could have a calendar of british mod inspired window view street shots.</td>', 'Super interesting photo. Not a typical calendar image in my view. But I suppose one could have a calendar of british mod inspired window view street shots.', '2011-06-13 14:31:43.000000', NULL, 1),
(6443082, 956680, 58634, '<td valign="top">Good DOF and angle. I like how you can see it''s "fingers" holding tightly to that nut. ;)<br/>I think it could use a bit more sharpness, especially around the face, but over all, very cute!</td>', 'Good DOF and angle. I like how you can see it''s "fingers" holding tightly to that nut. ;)I think it could use a bit more sharpness, especially around the face, but over all, very cute!', '2011-06-13 14:32:51.000000', NULL, 1),
(6443083, 956548, 58634, '<td valign="top">I like the abstract take on the challenge. The green colors throughout the whole image look very nice all blended together. What I don''t like is the big, lighter-colored blob right at the middle.</td>', 'I like the abstract take on the challenge. The green colors throughout the whole image look very nice all blended together. What I don''t like is the big, lighter-colored blob right at the middle.', '2011-06-13 14:33:52.000000', NULL, 1),
(6443084, 956683, 58634, '<td valign="top">Very lovely and simple silhouette. I like the warm colors, and the fact that I can almost sense a breeze in the air. No critique from me, good job!</td>', 'Very lovely and simple silhouette. I like the warm colors, and the fact that I can almost sense a breeze in the air. No critique from me, good job!', '2011-06-13 14:34:33.000000', NULL, 1),
(6443085, 956516, 58634, '<td valign="top">The skies are wicked. Would''ve preferred a bit more of a silhouette and a bit less sky, but it''s really a very nice image just the way it is.</td>', 'The skies are wicked. Would''ve preferred a bit more of a silhouette and a bit less sky, but it''s really a very nice image just the way it is.', '2011-06-13 14:35:28.000000', NULL, 1),
(6443088, 955877, 58634, '<td valign="top">I like the nice soft focus, and the pretty orange color that just pops out of the picture! I think having more white flowers in the background would''ve been a better touch instead of the empty dark space in between them.</td>', 'I like the nice soft focus, and the pretty orange color that just pops out of the picture! I think having more white flowers in the background would''ve been a better touch instead of the empty dark space in between them.', '2011-06-13 14:48:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6443096, 956554, 10785, '<td valign="top">I like how you got the entrance gate into the picture. It gives you an inviting feeling. One unfortunate side effect of that was to limit the color displayed. The small pink sails don''t really pop enough to offset the brown foreground that takes up half the photo or the dark blue/grey sky that takes up the other half. One thing I would have done differently would be to get closer to the colored sails maybe focusing on the group of three boats in the water. That would have had the effect of making that bright pop of pink a focal point of the otherwise drab and colorless landscape. You still could have gotten the mountains and water into the picture which would have given it that much needed environmental frame of reference. You do have good technicals including a good exposure and composition as well as a nice straight horizon which many people forget to look at.</td>', 'I like how you got the entrance gate into the picture. It gives you an inviting feeling. One unfortunate side effect of that was to limit the color displayed. The small pink sails don''t really pop enough to offset the brown foreground that takes up half the photo or the dark blue/grey sky that takes up the other half. One thing I would have done differently would be to get closer to the colored sails maybe focusing on the group of three boats in the water. That would have had the effect of making that bright pop of pink a focal point of the otherwise drab and colorless landscape. You still could have gotten the mountains and water into the picture which would have given it that much needed environmental frame of reference. You do have good technicals including a good exposure and composition as well as a nice straight horizon which many people forget to look at.', '2011-06-13 15:06:40.000000', NULL, 1),
(6443100, 956585, 77543, '<td valign="top">A superb shot that stands out from the rest.</td>', 'A superb shot that stands out from the rest.', '2011-06-13 15:10:26.000000', NULL, 1),
(6443101, 956629, 10785, '<td valign="top">Very good effort. I am not liking the lighting too much. It is somewhat uneven, dark around the edges and there are highlights and reflections on the upper part of the body with shadows on the lower part of the body. You exposed it well though. I would figure a beefcake calendar would picture the man holding the tire, not the other way around! lol!</td>', 'Very good effort. I am not liking the lighting too much. It is somewhat uneven, dark around the edges and there are highlights and reflections on the upper part of the body with shadows on the lower part of the body. You exposed it well though. I would figure a beefcake calendar would picture the man holding the tire, not the other way around! lol!', '2011-06-13 15:13:22.000000', NULL, 1),
(6443102, 956530, 17446, '<td valign="top">Added to my favorites.<br/>Very nice mood.</td>', 'Added to my favorites.Very nice mood.', '2011-06-13 15:17:45.000000', NULL, 1),
(6443105, 956759, 10785, '<td valign="top">Good composition though it is neither rule of thirds or really centered. The exposure is a little bright. I think the feet are an important part of the subject and ought to be in focus along with the frog bodies. That tells me you went a little too wide open with the aperture. because of that the photo is not quite sharp enough it is lacking in detailed textures. Great color!</td>', 'Good composition though it is neither rule of thirds or really centered. The exposure is a little bright. I think the feet are an important part of the subject and ought to be in focus along with the frog bodies. That tells me you went a little too wide open with the aperture. because of that the photo is not quite sharp enough it is lacking in detailed textures. Great color!', '2011-06-13 15:20:29.000000', NULL, 1),
(6443106, 956702, 10785, '<td valign="top">Just a little too much greenery. Probably moving closer would have helped. Maybe adjusting your angle.</td>', 'Just a little too much greenery. Probably moving closer would have helped. Maybe adjusting your angle.', '2011-06-13 15:21:07.000000', NULL, 1),
(6443107, 955906, 58634, '<td valign="top">So bold and gorgeous, I have no words. <br/>The lighting is MAGNIFICENT! Every color in here stands out so beautifully, I think I could stare at this forever.</td>', 'So bold and gorgeous, I have no words. The lighting is MAGNIFICENT! Every color in here stands out so beautifully, I think I could stare at this forever.', '2011-06-13 15:23:16.000000', NULL, 1),
(6443108, 956463, 10785, '<td valign="top">Such a cutie! I love how she is soooo into exploring the world around her.</td>', 'Such a cutie! I love how she is soooo into exploring the world around her.', '2011-06-13 15:23:33.000000', NULL, 1),
(6443112, 955998, 10785, '<td valign="top">Lovely color. I like that it isn''t tack sharp, but that does take away from the detail in the leaves a little. But that red color really pops!</td>', 'Lovely color. I like that it isn''t tack sharp, but that does take away from the detail in the leaves a little. But that red color really pops!', '2011-06-13 15:32:10.000000', NULL, 1),
(6443116, 956443, 10785, '<td valign="top">Great capture. Perhaps shooting from above, if possible, would have been a slightly better choice. I think the contrast is a little low here and could be pumped up.</td>', 'Great capture. Perhaps shooting from above, if possible, would have been a slightly better choice. I think the contrast is a little low here and could be pumped up.', '2011-06-13 15:34:48.000000', NULL, 1),
(6443117, 956692, 10785, '<td valign="top">Crazy pet pics calendar 2011!</td>', 'Crazy pet pics calendar 2011!', '2011-06-13 15:35:37.000000', NULL, 1),
(6443118, 956744, 10785, '<td valign="top">her super sharp eyes met mine as soon as I opened the photo. Nice job on the focal point. I think you got a hair too close though as the melon is slightly cut off. I think you needed more of that in for this environmental portrait.</td>', 'her super sharp eyes met mine as soon as I opened the photo. Nice job on the focal point. I think you got a hair too close though as the melon is slightly cut off. I think you needed more of that in for this environmental portrait.', '2011-06-13 15:37:11.000000', NULL, 1),
(6443120, 956312, 10785, '<td valign="top">I think you got a little too much on the right side of the photo and not enough of the top. A portrait orientation might have helped. Other than that, nice texture and the sharpness reveals the details.</td>', 'I think you got a little too much on the right side of the photo and not enough of the top. A portrait orientation might have helped. Other than that, nice texture and the sharpness reveals the details.', '2011-06-13 15:39:09.000000', NULL, 1),
(6443122, 956632, 10785, '<td valign="top">Very good use of DoF to put the focal point right on your subject. For blueberries they seem a hair green. It seems the entire picture has a green cast on it perhaps due to the reflection of the light off the green foliage. Not sure how to counter that except to selectively lower the green channel in PP.</td>', 'Very good use of DoF to put the focal point right on your subject. For blueberries they seem a hair green. It seems the entire picture has a green cast on it perhaps due to the reflection of the light off the green foliage. Not sure how to counter that except to selectively lower the green channel in PP.', '2011-06-13 15:41:10.000000', NULL, 1),
(6443150, 955984, 133346, '<td valign="top">Reminds me of "Good fellas" the movie....mafioso pigeons he he!!</td>', 'Reminds me of "Good fellas" the movie....mafioso pigeons he he!!', '2011-06-13 16:35:09.000000', NULL, 1),
(6443157, 956611, 133346, '<td valign="top">amasing shot!pugs are so full emotions!!I have a pug too, she is talking to me with her eyes.well done!</td>', 'amasing shot!pugs are so full emotions!!I have a pug too, she is talking to me with her eyes.well done!', '2011-06-13 16:44:38.000000', NULL, 1),
(6443167, 956687, 67258, '<td valign="top">A bit too heavy on the saturation for my taste, otherwise a pleasant photograph.</td>', 'A bit too heavy on the saturation for my taste, otherwise a pleasant photograph.', '2011-06-13 17:09:43.000000', NULL, 1),
(6443170, 955906, 86090, '<td valign="top">Wow! I don''t know what to say, except that I love it. 10</td>', 'Wow! I don''t know what to say, except that I love it. 10', '2011-06-13 17:17:31.000000', NULL, 1),
(6443173, 956715, 86090, '<td valign="top">So beautiful!</td>', 'So beautiful!', '2011-06-13 17:19:56.000000', NULL, 1),
(6443175, 956090, 108069, '<td valign="top">Ahhh, I used to live there. Well, not in the castle or St. Vitus, but in Vrsovice. A very nice shot with pleasing tones. Nice long exposure to get the most out of the Vltava. Oh the memories.</td>', 'Ahhh, I used to live there. Well, not in the castle or St. Vitus, but in Vrsovice. A very nice shot with pleasing tones. Nice long exposure to get the most out of the Vltava. Oh the memories.', '2011-06-13 17:24:50.000000', NULL, 1),
(6443177, 956628, 108069, '<td valign="top">So much fun in one picture. This is an absolutely delight.</td>', 'So much fun in one picture. This is an absolutely delight.', '2011-06-13 17:25:25.000000', NULL, 1),
(6443192, 956659, 65319, '<td valign="top">Wow...this kitty is gorgeous!</td>', 'Wow...this kitty is gorgeous!', '2011-06-13 18:05:54.000000', NULL, 1),
(6443198, 956689, 45631, '<td valign="top">This is a great capture but the crop seems to make the flower dominate for me.</td>', 'This is a great capture but the crop seems to make the flower dominate for me.', '2011-06-13 18:15:01.000000', NULL, 1),
(6443200, 956530, 45631, '<td valign="top">I like this image but don''t like that the birds are cut off on the edges of the frame.  a bit of a wing cut off on the one on the bottom left works OK but I find the others distracting.</td>', 'I like this image but don''t like that the birds are cut off on the edges of the frame.  a bit of a wing cut off on the one on the bottom left works OK but I find the others distracting.', '2011-06-13 18:19:51.000000', NULL, 1),
(6443219, 956670, 60495, '<td valign="top">I love the photo with the exception of the board in the fore ground, other than that I feel the look and feel of the shot would make it a nice calendar image.</td>', 'I love the photo with the exception of the board in the fore ground, other than that I feel the look and feel of the shot would make it a nice calendar image.', '2011-06-13 19:16:26.000000', NULL, 1),
(6443224, 956542, 60495, '<td valign="top">I looked at this shot and my first reaction was why all the open space (no pun intended), the open space, at least to me does not seem to add anything to the shot and the few stars that are visible left me wanting either more stars or less background. If I was voting, this shot would likely would have been given a five by me mainly because it does not fully convey a true sense of what the subject should be, is it the moon which is pretty cool or is it the moon and the stars which is not so cool. Good luck in the challenge.</td>', 'I looked at this shot and my first reaction was why all the open space (no pun intended), the open space, at least to me does not seem to add anything to the shot and the few stars that are visible left me wanting either more stars or less background. If I was voting, this shot would likely would have been given a five by me mainly because it does not fully convey a true sense of what the subject should be, is it the moon which is pretty cool or is it the moon and the stars which is not so cool. Good luck in the challenge.', '2011-06-13 19:25:22.000000', NULL, 1),
(6443226, 956235, 60495, '<td valign="top">Nice idea but to me the camera placement just seems odd, shooting across the fairway seem to lose the effect you were going for, to me you lost the sense of a fairway in the foreground and ended up with just a grassy area. If possible the shot that may have worked better was finding a fairway in line with the mountains and shoot from the tee box using the lines of the fairway to lead into the mountains. Hope the critique helps, good luck in the challenge</td>', 'Nice idea but to me the camera placement just seems odd, shooting across the fairway seem to lose the effect you were going for, to me you lost the sense of a fairway in the foreground and ended up with just a grassy area. If possible the shot that may have worked better was finding a fairway in line with the mountains and shoot from the tee box using the lines of the fairway to lead into the mountains. Hope the critique helps, good luck in the challenge', '2011-06-13 19:33:46.000000', NULL, 1),
(6443235, 956721, 58634, '<td valign="top">Busy image. Not sure what''s supposed to be the main element in the image. Personally, I also don''t like the cartoony effect to it, either.</td>', 'Busy image. Not sure what''s supposed to be the main element in the image. Personally, I also don''t like the cartoony effect to it, either.', '2011-06-13 20:03:04.000000', NULL, 1),
(6443236, 956698, 58634, '<td valign="top">flower looks beautiful but the background doesn''t work for me.  I like that the bug seems to be staring right at the camera.</td>', 'flower looks beautiful but the background doesn''t work for me.  I like that the bug seems to be staring right at the camera.', '2011-06-13 20:03:58.000000', NULL, 1),
(6443237, 956659, 58634, '<td valign="top">I really like your composition, and enjoy the fact that you left this horizontal instead of making it vertical. I like the soft focus on the red and the cat, and the sharpness and boldness of the cat''s eyes. good job.</td>', 'I really like your composition, and enjoy the fact that you left this horizontal instead of making it vertical. I like the soft focus on the red and the cat, and the sharpness and boldness of the cat''s eyes. good job.', '2011-06-13 20:05:24.000000', NULL, 1),
(6443238, 956664, 58634, '<td valign="top">Concept is excellent, but the image seems washed out. It needs contrast.</td>', 'Concept is excellent, but the image seems washed out. It needs contrast.', '2011-06-13 20:05:55.000000', NULL, 1),
(6443239, 956568, 58634, '<td valign="top">I like the soft lighting in the flower, and the shallow DOF. It adds a certain something to the photograph. Lovely.</td>', 'I like the soft lighting in the flower, and the shallow DOF. It adds a certain something to the photograph. Lovely.', '2011-06-13 20:07:11.000000', NULL, 1),
(6443240, 956617, 58634, '<td valign="top">I think it''s interesting that you went with this composition. It works, but I wonder what the image would look like if rotated 180?<br/>I enjoy the rich, warm brown colors and the different textures in this image. Good job!</td>', 'I think it''s interesting that you went with this composition. It works, but I wonder what the image would look like if rotated 180?I enjoy the rich, warm brown colors and the different textures in this image. Good job!', '2011-06-13 20:08:28.000000', NULL, 1),
(6443242, 956737, 58634, '<td valign="top">I wish the person and paddleboard were eithe a complete silhouette, or had better lighting. I''m not a fan of the weird color green at the bottom of the image but on the flip side, I like the blue colors at the top. I think a different angle would''ve improved this image.</td>', 'I wish the person and paddleboard were eithe a complete silhouette, or had better lighting. I''m not a fan of the weird color green at the bottom of the image but on the flip side, I like the blue colors at the top. I think a different angle would''ve improved this image.', '2011-06-13 20:10:28.000000', NULL, 1),
(6443244, 956756, 58634, '<td valign="top">Soft, and dreamy and glorious. Why the sepia tone? I wish there was less ''water'' and more elements to this picture.</td>', 'Soft, and dreamy and glorious. Why the sepia tone? I wish there was less ''water'' and more elements to this picture.', '2011-06-13 20:11:30.000000', NULL, 1),
(6443246, 956535, 58634, '<td valign="top">Pretty flower, but I don''t think the angle at which you took the picture emphasized it''s beauty at it''s best due to the awkward shadows created. It also makes it look pretty flat and I would love for it to look more 3D-ish.</td>', 'Pretty flower, but I don''t think the angle at which you took the picture emphasized it''s beauty at it''s best due to the awkward shadows created. It also makes it look pretty flat and I would love for it to look more 3D-ish.', '2011-06-13 20:12:34.000000', NULL, 1),
(6443339, 955984, 30214, '<td valign="top">nice composition, and beautiful BW tones, just slightly oversharpened around the pigeons (hehehe!)</td>', 'nice composition, and beautiful BW tones, just slightly oversharpened around the pigeons (hehehe!)', '2011-06-13 22:30:37.000000', NULL, 1),
